<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
require_login();
if (!has_permission('lab.requests.view') && !has_permission('lab.results.view')) { http_response_code(403); exit('Laboratory access is not assigned to your account.'); }
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $action=(string)($_POST['action']??'');
    if($action==='request'){
        require_permission('lab.requests.create'); $patientId=filter_var($_POST['patient_id']??'',FILTER_VALIDATE_INT); $name=trim((string)($_POST['test_name']??''));
        if(!$patientId||$name===''||strlen($name)>160){set_flash('danger','Choose a patient and enter a test name up to 160 characters.');redirect('/hospital%20management/laboratory/index.php');}
        if(current_user()['role_key']==='doctor'){$check=$pdo->prepare('SELECT id FROM visits WHERE patient_id=:patient AND doctor_id=(SELECT id FROM doctors WHERE user_id=:user) LIMIT 1');$check->execute(['patient'=>$patientId,'user'=>current_user()['id']]);if(!$check->fetch()){set_flash('danger','You can only request tests for a patient you have consulted.');redirect('/hospital%20management/laboratory/index.php');}}
        $q=$pdo->prepare('INSERT INTO lab_tests (patient_id,requested_by,test_name) VALUES (:patient,:user,:name)');$q->execute(['patient'=>$patientId,'user'=>current_user()['id'],'name'=>$name]);$id=(string)$pdo->lastInsertId();record_audit('create','lab_test',$id,'Laboratory test requested');notify_staff('lab_test_requested','lab_test',$id,current_user()['full_name'].' requested a lab test: '.$name.'.');set_flash('success','Laboratory test requested.');
    } elseif($action==='result'){
        require_permission('lab.results.manage'); $id=filter_var($_POST['test_id']??'',FILTER_VALIDATE_INT);$result=trim((string)($_POST['result']??''));
        if(!$id||$result===''||strlen($result)>20000){set_flash('danger','A test and result of up to 20,000 characters are required.');redirect('/hospital%20management/laboratory/index.php');}
        $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT id FROM lab_tests WHERE id=:id AND status IN (\'requested\',\'in_progress\') FOR UPDATE');$q->execute(['id'=>$id]);if(!$q->fetch())throw new RuntimeException('Test not found or already completed.');$q=$pdo->prepare('INSERT INTO lab_results (lab_test_id,result,recorded_by) VALUES (:id,:result,:user) ON DUPLICATE KEY UPDATE result=VALUES(result),recorded_by=VALUES(recorded_by),recorded_at=CURRENT_TIMESTAMP');$q->execute(['id'=>$id,'result'=>$result,'user'=>current_user()['id']]);$pdo->prepare("UPDATE lab_tests SET status='completed' WHERE id=:id")->execute(['id'=>$id]);record_audit('complete','lab_test',(string)$id,'Laboratory result recorded');notify_staff('lab_result_recorded','lab_test',(string)$id,current_user()['full_name'].' recorded a laboratory result.');$pdo->commit();set_flash('success','Laboratory result saved.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();set_flash('danger',$e instanceof RuntimeException?$e->getMessage():'Result could not be saved.');}
    } else {http_response_code(400);exit('Unknown laboratory action.');}
    redirect('/hospital%20management/laboratory/index.php');
}
$sql='SELECT t.id,t.patient_id,t.test_name,t.status,t.requested_at,p.patient_no,p.first_name,p.last_name,r.result,u.full_name AS recorded_by FROM lab_tests t JOIN patients p ON p.id=t.patient_id LEFT JOIN lab_results r ON r.lab_test_id=t.id LEFT JOIN users u ON u.id=r.recorded_by';$params=[];if(current_user()['role_key']==='doctor'){$sql.=' WHERE t.requested_by=:user';$params['user']=current_user()['id'];}$sql.=' ORDER BY t.requested_at DESC LIMIT 200';$q=$pdo->prepare($sql);$q->execute($params);$tests=$q->fetchAll();
$patients=[];if(has_permission('lab.requests.create')){if(current_user()['role_key']==='doctor'){$q=$pdo->prepare('SELECT DISTINCT p.id,p.patient_no,p.first_name,p.last_name FROM patients p JOIN visits v ON v.patient_id=p.id JOIN doctors d ON d.id=v.doctor_id WHERE d.user_id=:user ORDER BY p.last_name,p.first_name LIMIT 1000');$q->execute(['user'=>current_user()['id']]);$patients=$q->fetchAll();}else{$patients=$pdo->query('SELECT id,patient_no,first_name,last_name FROM patients ORDER BY last_name,first_name LIMIT 1000')->fetchAll();}}
$pageTitle='Laboratory';require __DIR__.'/../includes/header.php'; ?>
<div class="page-heading"><div><h2>Laboratory</h2><p>Track requested tests, enter results, and return findings to the care team.</p></div></div>
<?php if(has_permission('lab.requests.create')): ?><section class="content-card form-card mt-0"><div class="card-heading"><h3>Request test</h3></div><form method="post" class="row g-3"><?= csrf_field() ?><input type="hidden" name="action" value="request"><div class="col-md-5"><label class="form-label">Patient</label><select class="form-select" name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['patient_no'].' · '.$p['last_name'].', '.$p['first_name']) ?></option><?php endforeach; ?></select></div><div class="col-md-5"><label class="form-label">Test</label><input class="form-control" name="test_name" maxlength="160" placeholder="e.g. Full blood count" required></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Request</button></div></form></section><?php endif; ?>
<section class="content-card"><div class="table-responsive"><table class="table"><thead><tr><th>Requested</th><th>Patient</th><th>Test</th><th>Status</th><th>Result / action</th></tr></thead><tbody><?php if(!$tests): ?><tr><td class="empty-state" colspan="5">No laboratory requests.</td></tr><?php else: foreach($tests as $t): ?><tr><td><?= e(date('M j, Y g:i a',strtotime($t['requested_at']))) ?></td><td><a href="/hospital%20management/patient/show.php?id=<?= (int)$t['patient_id'] ?>"><?= e($t['last_name'].', '.$t['first_name']) ?></a><br><span class="subtle"><?= e($t['patient_no']) ?></span></td><td><?= e($t['test_name']) ?></td><td><?= e(ucfirst(str_replace('_',' ',$t['status']))) ?></td><td><?php if($t['result']!==null): ?><details><summary>View result</summary><?= nl2br(e($t['result'])) ?><br><small>Recorded by <?= e($t['recorded_by']??'Staff') ?></small></details><?php elseif(has_permission('lab.results.manage')): ?><form method="post" class="d-flex gap-2"><?= csrf_field() ?><input type="hidden" name="action" value="result"><input type="hidden" name="test_id" value="<?= (int)$t['id'] ?>"><textarea class="form-control" name="result" rows="2" maxlength="20000" placeholder="Enter result" required></textarea><button class="btn btn-sm btn-primary">Complete</button></form><?php else: ?>Awaiting result<?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
